"""
gerar_wasm.py — Gera public/wasm/physics.wasm a partir do binário pré-compilado.

O binário abaixo (base64) foi compilado de physics.c com:
  clang --target=wasm32-unknown-unknown -O2 -nostdlib \
        -Wl,--no-entry -Wl,--export-all -Wl,--allow-undefined \
        -o physics.wasm physics.c

Uso:
  python gerar_wasm.py

Isso cria public/wasm/physics.wasm. Rode uma vez e pode apagar este script
(ou manter pra regenerar). O .wasm é o que o jogo realmente carrega.
"""
import base64
import os

WASM_B64 = ""

def main():
    aqui = os.path.dirname(os.path.abspath(__file__))
    destino = os.path.join(aqui, "physics.wasm")
    with open(destino, "wb") as f:
        f.write(base64.b64decode(WASM_B64))
    tamanho = os.path.getsize(destino)
    print(f"OK -> {destino} ({tamanho} bytes)")
    print("Recarregue o jogo. No console (F2 ou DevTools) deve aparecer:")
    print("  [WASM] physics.wasm carregado")

if __name__ == "__main__":
    main()
